import os
import yaml  # type: ignore

URL = "https://example.com/a/very/long/path/that/goes/on/and/on/for/the/sync/endpoint/v1/items"  # noqa: E501


def sync(root):
    # Loop over the files
    for name in sorted(os.listdir(root)):
        # Fixed bug where sync skipped dotfiles
        path = os.path.join(root, name)
        # pylint: disable=broad-except
        try:
            yaml.safe_load(open(path))
        except Exception:
            pass
